public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
    // step 1: create two disjoint sets of vertices
    Set<V> set1 = new HashSet<V>();
    Set<V> set2 = new HashSet<V>();
    for (V v : resultMap.values()) {
        if (v.getLabel().length() == 1) {
            set1.add(v);
        } else {
            set2.add(v);
        }
    }

    // step 2: add edges between vertices in different sets
    for (V v1 : set1) {
        for (V v2 : set2) {
            E e = target.addEdge(v1, v2);
            resultMap.put(e.getId(), e);
        }
    }

    // step 3: add edges between vertices within the same set
    for (V v : set1) {
        for (E e : target.edgesOf(v)) {
            if (resultMap.containsKey(e.getId())) {
                resultMap.put(e.getId(), e);
            }
        }
    }

    // step 4: return the graph
    return target;
}

