    long timeBucketMinute = (timeBucket - timeBucketYear * 100000000 - timeBucketMonth * 10000 - timeBucketDay * 100 - timeBucketHour * 10000) / 100;
    long timeBucketSecond = (timeBucket - timeBucketYear * 100000000 - timeBucketMonth * 10000 - timeBucketDay * 100 - timeBucketHour * 10000 - timeBucketMinute * 100);
    long dayAdder = dayStep == 10 ? 1 : dayStep == 5 ? 2 : dayStep == 3 ? 4 : dayStep == 2 ? 7 : dayStep == 1 ? 14 : 0;
    long year = timeBucketYear + (long)Math.floor(timeBucketMonth / 12.0) + dayAdder / 365.0;
    long month = (timeBucketMonth + dayAdder % 12) % 12;
    long day = timeBucketDay + dayAdder % 30;
    long hour = timeBucketHour + (dayAdder % 24);
    long minute = timeBucketMinute + ((dayAdder % 60) / 10);
    long second = timeBucketSecond + ((dayAdder % 60) % 10);
    return year * 100000000 + month * 10000 + day * 100 + hour * 10000 + minute * 100 + second * 10 + timeBucketDay % 10;
