    // Initialize the path
    GraphPath<V,E> path = new GraphPathImpl<>(graph);

    // Iterate over the edges of the tour
    for (E edge : tour) {
        // Add the edge to the path
        path.appendEdge(edge);
    }

    // Return the resulting path
    return path;
}

