private GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Initialize the tour graph path
    GraphPath<V, E> tourPath = new GraphPath<V, E>(graph);
    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Get the source and target vertices of the edge
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        // Add the edge to the tour path
        tourPath.addEdge(edge);
        // If the edge starts a new subpath, add a new vertex to the tour path
        if (!tourPath.getVertexList().contains(source)) {
            tourPath.addVertex(source);
        }
        // If the edge ends a subpath, add a new vertex to the tour path
        if (!tourPath.getVertexList().contains(target)) {
            tourPath.addVertex(target);
        }
    }
    // Return the transformed tour graph path
    return tourPath;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    GraphPath<V, E> path = new GraphPath<>(graph);
    for (E edge : tour) {
        path.addEdge(edge);
    }
    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Initialize a GraphPath object to store the tour
    GraphPath<V,E> tourPath = new GraphPath<V,E>(graph);

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Get the endpoints of the current edge
        Vertex source = graph.getEdgeSource(edge);
        Vertex target = graph.getEdgeTarget(edge);

        // Add the edge to the tour path
        tourPath.addEdge(edge);

        // Add the vertices between the source and target of the edge to the tour path
        for (Vertex vertex : graph.getVerticesBetween(source, target)) {
            tourPath.addVertex(vertex);
        }
    }

    return tourPath;
}

