String function (String input) {
    if (input == null) {
        return null;
    }

    StringBuilder output = new StringBuilder();

    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        switch (c) {
            case '\\':
                if (i + 1 < input.length()) {
                    char next = input.charAt(i + 1);
                    switch (next) {
                        case 'b':
                            output.append('\b');
                            i++;
                            break;
                        case 't':
                            output.append('\t');
                            i++;
                            break;
                        case 'n':
                            output.append('\n');
                            i++;
                            break;
                        case 'f':
                            output.append('\f');
                            i++;
                            break;
                        case 'r':
                            output.append('\r');
                            i++;
                            break;
                        case '\\':
                            output.append('\\');
                            i++;
                            break;
                        case 'u':
                            if (i + 4 < input.length()) {
                                String unicode = input.substring(i + 2, i + 6);
                                output.append((char) Integer.parseInt(unicode, 16));
                                i += 5;
                            }
                            break;
                    }
                }
                break;
            default:
                output.append(c);
                break;
        }
    }

    return output.toString();
}

