public boolean isCompatible(DataTable dataset) {
    // Check if the provided dataset is not null
    if (dataset == null) {
        throw new IllegalArgumentException("The provided dataset cannot be null.");
    }

    // Check if the datasets have the same number of rows
    if (data.length != dataset.getRowCount()) {
        return false;
    }

    // Check if the datasets have the same number of columns
    if (data[0].length != dataset.getColumnCount()) {
        return false;
    }

    // Check if the datasets have the same datatypes for each column
    for (int i = 0; i < data[0].length; i++) {
        if (!data.getType(i).equals(dataset.getType(i))) {
            return false;
        }
    }

    // Check if the datasets have the same data in each cell
    for (int i = 0; i < data.length; i++) {
        for (int j = 0; j < data[0].length; j++) {
            if (!data[i][j].equals(dataset.getValue(i, j))) {
                return false;
            }
        }
    }

    // If all the checks have passed, the datasets are compatible
    return true;
}

