private List<Pair<List<Pair<Integer, Integer>>, E>> computeMinimalSeparators(E edge) {
    // Compute the neighbors of the incident vertices
    List<V> incidentVertices = graph.getVertices();
    List<V> neighbors = graph.getNeighbors(incidentVertices.get(0));
    if (neighbors.contains(incidentVertices.get(1))) {
        neighbors.remove(incidentVertices.get(1));
    }
    // Compute the minimal separators of the neighborhood
    List<Pair<List<Pair<Integer, Integer>>, E>> minimalSeparators = new ArrayList<>();
    for (V neighbor : neighbors) {
        // Compute the minimal separator of the neighborhood
        List<Pair<Integer, Integer>> minimalSeparator = computeMinimalSeparator(neighbor);
        if (minimalSeparator.size() > 1) {
            // Add the minimally separated separator to the list of minimal separators
            minimalSeparators.add(new Pair<>(minimalSeparator, edge));
        }
    }
    return minimalSeparators;
}

/**
 * Computes the minimal separator of the given vertex.
 * @param vertex the vertex whose minimal separator is computed
 * @return a list of pairs, where each pair represents an incident edge of the vertex
 */
private List<Pair<Integer, Integer>> computeMinimalSeparator(V vertex) {
    // Compute the incident edges of the vertex
    List<E> incidentEdges = graph.getEdges();
    // Create a set of neighbors of the vertex
    Set<V> neighbors = new HashSet<>();
    for (E edge : incidentEdges) {
        if (graph.getVertices()
                .contains(graph.getOtherVertex(edge, vertex))) {
            neighbors.add(graph.getOtherVertex(edge, vertex));
        }
    }
    // Create a list of minimal separators of the vertex
    List<Pair<Integer, Integer>> minimalSeparators = new ArrayList<>();
    // Iterate over all incident edges of the vertex
    for (E edge : incidentEdges) {
        List<V> edgeNeighbors = new ArrayList<>(neighbors);
        edgeNeighbors.remove(graph.getOtherVertex(edge, vertex));
        // Add the edge to the minimal separator if it separates the vertex from its neighbors
        if (edgeNeighbors.size() == 1) {
            minimalSeparators.add(new Pair<>((int) edge.hashCode(), (int) edge.hashCode()));
        }
    }
    return minimalSeparators;
}

