private void addReverse(final File[] files) {
    // Check for null or empty input
    if (files == null || files.length == 0) {
        return;
    }

    // Reverse the array of files
    File[] reversedFiles = Arrays.copyOf(files, files.length);
    Arrays.sort(reversedFiles);
    Collections.reverse(List.of(reversedFiles));

    // Add the files in reverse order
    for (File file : reversedFiles) {
        add(file);
    }
}

