public static String applyRelativePath(String path, String relativePath) {
    // Split the path into its component parts
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Iterate through the relative path parts and apply them to the base path
    for (String relativePathPart : relativePathParts) {
        if (relativePathPart.equals("..")) {
            // If the relative path part is "..", remove the last part of the base path
            pathParts = Arrays.copyOfRange(pathParts, 0, pathParts.length - 1);
        } else if (!relativePathPart.equals(".")) {
            // If the relative path part is not ".", add it to the base path
            pathParts = Arrays.copyOf(pathParts, pathParts.length + 1);
            pathParts[pathParts.length - 1] = relativePathPart;
        }
    }

    // Join the modified path parts into a single string
    String newPath = String.join("/", pathParts);

    return newPath;
}

public static String applyRelativePath(String path, String relativePath) {
    int lastSeparatorIndex = path.lastIndexOf("/");
    if (lastSeparatorIndex == -1) {
        // No separator found, use entire path and relative path
        return relativePath;
    }
    return path.substring(0, lastSeparatorIndex + 1) + relativePath;
}

