public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Initialize the output list
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Check if the file exists and is not empty
    if (file.exists() && file.length() > 0) {
        // Open the file for reading
        BufferedReader reader = new BufferedReader(new FileReader(file));

        // Read the file line by line
        String line;
        while ((line = reader.readLine()) != null) {
            // Skip comments and empty lines
            if (line.startsWith("#") || line.trim().isEmpty()) {
                continue;
            }

            // Split the line into tokens using the delimiter
            String[] tokens = line.split("\\s+");

            // Check if the line is not a header line
            if (!tokens[0].equals("T")) {
                continue;
            }

            // Get the thread ID and snapshot time
            int threadId = Integer.parseInt(tokens[1]);
            long snapshotTime = Long.parseLong(tokens[2]);

            // Check if the snapshot time is within the specified time range
            boolean inTimeRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (snapshotTime >= range.startTime && snapshotTime <= range.endTime) {
                    inTimeRange = true;
                    break;
                }
            }

            // If the snapshot time is within the time range, add the thread snapshot to the output list
            if (inTimeRange) {
                threadSnapshots.add(new ThreadSnapshot(threadId, snapshotTime));
            }
        }

        // Close the file
        reader.close();
    }

    return threadSnapshots;
}

