public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("id")) {
                // skip the header line
                continue;
            }
            String[] tokens = line.split(",");
            long timestamp = Long.parseLong(tokens[1]);
            String threadName = tokens[3];
            int threadId = Integer.parseInt(tokens[4]);
            if (timeRanges == null || timeRanges.isEmpty()) {
                // no time range specified, add all snapshots
                snapshots.add(new ThreadSnapshot(timestamp, threadName, threadId));
            } else {
                // check if the snapshot falls within the specified time range
                ProfileAnalyzeTimeRange matchingTimeRange = null;
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                        matchingTimeRange = timeRange;
                        break;
                    }
                }
                if (matchingTimeRange != null) {
                    // add the snapshot to the list
                    snapshots.add(new ThreadSnapshot(timestamp, threadName, threadId, matchingTimeRange));
                }
            }
        }
    }
    return snapshots;
}
